'use strict';

// MODULES //

var tape = require( 'tape' );
var hasBigIntSupport = require( '@stdlib/assert/has-bigint-support' );
var BigInt = require( '@stdlib/bigint/ctor' );
var UINT32_MAX = require( '@stdlib/constants/uint32/max' );
var isEqual = require( '@stdlib/number/int64/base/assert/is-equal' );
var Int64 = require( '@stdlib/number/int64/ctor' );
var discreteUniform = require( '@stdlib/random/array/discrete-uniform' );
var add = require( './../lib' );


// VARIABLES //

var opts = {
	'skip': !hasBigIntSupport()
};


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof add, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function adds two 64-bit signed integers', function test( t ) {
	var expected;
	var out;
	var a;
	var b;

	// Small values:
	a = new Int64( 5 );
	b = new Int64( 10 );
	out = add( a, b );
	expected = new Int64( 15 );
	t.ok( isEqual( out, expected ), 'returns expected value' );

	// Zero:
	a = new Int64( 5 );
	b = new Int64( 0 );
	out = add( a, b );
	expected = new Int64( 5 );
	t.ok( isEqual( out, expected ), 'returns expected value' );

	// Negative values:
	a = new Int64( -5 );
	b = new Int64( 5 );
	out = add( a, b );
	expected = new Int64( 0 );
	t.ok( isEqual( out, expected ), 'returns expected value' );

	a = new Int64( -10 );
	b = new Int64( -20 );
	out = add( a, b );
	expected = new Int64( -30 );
	t.ok( isEqual( out, expected ), 'returns expected value' );

	// Overflow wrapping (two's complement):
	a = new Int64( BigInt( '9223372036854775807' ) ); // 2^63 - 1
	b = new Int64( 1 );
	out = add( a, b );
	expected = new Int64( BigInt( '-9223372036854775808' ) ); // -2^63
	t.ok( isEqual( out, expected ), 'returns expected value' );

	t.end();
});

tape( 'the function adds two 64-bit signed integers (random values)', opts, function test( t ) {
	var big64sum;
	var expected;
	var values;
	var out;
	var a;
	var b;
	var x;
	var i;

	x = discreteUniform( 100, 0, UINT32_MAX, {
		'dtype': 'uint32'
	});
	values = [];
	for ( i = 0; i < x.length; i++ ) {
		values.push( Int64.of( x[ i ], x[ ( i+1 ) % x.length ] ) );
	}

	for ( i = 0; i < values.length; i++ ) {
		a = values[ i ];
		b = values[ ( i+1 ) % values.length ];
		out = add( a, b );
		big64sum = BigInt.asIntN( 64, a.valueOf() + b.valueOf() );
		expected = new Int64( big64sum );
		t.ok( isEqual( out, expected ), 'returns expected value' );
	}

	t.end();
});
